package com.afirma.assina;
import java.util.*;
import java.security.SecureRandom;
import java.time.OffsetDateTime;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.core.env.Environment;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@Service
public class ContaAutentica {
 private final BancoAssineai banco;private final AutenticaPersistencia persistencia;private final ObjectProvider<JavaMailSender> emails;private final Environment ambiente;
 public ContaAutentica(BancoAssineai banco,AutenticaPersistencia persistencia,ObjectProvider<JavaMailSender> emails,Environment ambiente){this.banco=banco;this.persistencia=persistencia;this.emails=emails;this.ambiente=ambiente;}
 @Transactional public void solicitar(String email){RegrasAutentica.exigir(email!=null&&email.length()<=254,"E-mail inválido");if(emails.getIfAvailable()==null||Objects.toString(ambiente.getProperty("spring.mail.host"),"").isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Recuperação por e-mail não configurada");var usuarios=banco.listar("SELECT u.* FROM autentica_identidade.\"Usuario\" u JOIN autentica.\"Cliente\" c ON c.id=u.\"UsuarioClienteId\" WHERE lower(u.\"UsuarioEmail\")=lower(:e) AND NOT COALESCE(u.\"UsuarioBloqueado\",false) AND COALESCE(c.\"ClienteStatus\",true)",Map.of("e",email));if(usuarios.size()!=1)return;var u=usuarios.getFirst();banco.um("SELECT id FROM autentica_identidade.\"Usuario\" WHERE id=:id FOR UPDATE",Map.of("id",u.get("id")));var recente=banco.um("SELECT usuario_id FROM firma_autentica_recuperacao WHERE usuario_id=:id AND solicitada_em>now()-interval '1 minute'",Map.of("id",u.get("id")));if(recente!=null)return;String codigo=String.format("%06d",new SecureRandom().nextInt(1000000));persistencia.gravar("Usuario",((Number)u.get("id")).longValue(),Map.of("UsuarioRecSenhaToken",codigo,"UsuarioRecSenhaTokenTempoExpirar",OffsetDateTime.now().plusMinutes(10)));banco.executar("INSERT INTO firma_autentica_recuperacao(usuario_id) VALUES(:id) ON CONFLICT(usuario_id) DO UPDATE SET tentativas=0,solicitada_em=now()",Map.of("id",u.get("id")));var m=new SimpleMailMessage();m.setTo(email);m.setFrom(ambiente.getProperty("APP_EMAIL_FROM",ambiente.getProperty("spring.mail.username","FIRMA@localhost")));m.setSubject("FIRMA · Recuperar acesso");m.setText("Seu código para recuperar o acesso à FIRMA é "+codigo+". Ele expira em 10 minutos. Se não solicitou, ignore esta mensagem.");emails.getObject().send(m);}
 // Tentativas inválidas precisam persistir mesmo quando o pedido é recusado.
 @Transactional(noRollbackFor=ResponseStatusException.class)public void redefinir(String email,String codigo,String senha){RegrasAutentica.exigir(senha!=null&&senha.length()>=8&&senha.length()<=256,"A senha deve ter entre 8 e 256 caracteres");var usuarios=banco.listar("SELECT u.* FROM autentica_identidade.\"Usuario\" u WHERE lower(u.\"UsuarioEmail\")=lower(:e) AND NOT COALESCE(u.\"UsuarioBloqueado\",false) FOR UPDATE",Map.of("e",Objects.toString(email,"")));if(usuarios.size()!=1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Código inválido ou expirado");var u=usuarios.getFirst();var permitido=banco.um("UPDATE firma_autentica_recuperacao SET tentativas=tentativas+1 WHERE usuario_id=:id AND tentativas<5 RETURNING usuario_id",Map.of("id",u.get("id")));boolean valido=permitido!=null&&codigo!=null&&codigo.matches("[0-9]{6}")&&java.security.MessageDigest.isEqual(codigo.getBytes(java.nio.charset.StandardCharsets.UTF_8),Objects.toString(u.get("UsuarioRecSenhaToken"),"").getBytes(java.nio.charset.StandardCharsets.UTF_8));var prazo=banco.um("SELECT id FROM autentica_identidade.\"Usuario\" WHERE id=:id AND \"UsuarioRecSenhaTokenTempoExpirar\">now()",Map.of("id",u.get("id")));if(!valido||prazo==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Código inválido ou expirado");trocar(((Number)u.get("id")).longValue(),senha);}
 private void trocar(long id,String senha){var credencial=SenhaAutentica.criar(senha);var v=new HashMap<String,Object>();v.put("UsuarioSenha",credencial.hash());v.put("UsuarioRandomBytes",credencial.sal());v.put("UsuarioRecSenhaToken",null);v.put("UsuarioRecSenhaTokenTempoExpirar",null);persistencia.gravar("Usuario",id,v);banco.executar("UPDATE autentica_identidade.\"Sessao\" SET \"SessaoStatus\"='F' WHERE \"UsuarioId\"=:id",Map.of("id",id));banco.executar("DELETE FROM firma_autentica_recuperacao WHERE usuario_id=:id",Map.of("id",id));}
 @Transactional public void senha(ServicoAutentica.Contexto c,String atual,String nova){RegrasAutentica.exigir(c.usuario()>0,"Use o perfil da empresa para gerenciar a conta proprietária");RegrasAutentica.exigir(nova!=null&&nova.length()>=8&&nova.length()<=256,"A senha deve ter entre 8 e 256 caracteres");var u=banco.um("SELECT * FROM autentica_identidade.\"Usuario\" WHERE id=:id AND \"UsuarioClienteId\"=:c FOR UPDATE",Map.of("id",c.usuario(),"c",c.cliente()));if(u==null||!SenhaAutentica.verificar(Objects.toString(atual,""),Objects.toString(u.get("UsuarioSenha"),""),Objects.toString(u.get("UsuarioRandomBytes"),"")))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Senha atual inválida");trocar(c.usuario(),nova);}
}
